      "stepIndex": stepIndex,
      "hopIndex": hopIndex,
      "expectedOut": expectedOut,
      "realisedOut": realisedOut,
      "shortfall": shortfall,
      "shortfallRatio": shortfallRatio,
      "scale": scale,
      "verdict": verdict,
      "reason": reason,
      "resizedSteps": resized
