          // {"code":"400100","msg":"order_not_exist_or_not_allow_to_cancel"}, same condition as the spaced variant above, see https://github.com/ccxt/ccxt/issues/24154
          "Order size below the minimum requirement.": InvalidOrder,
          // {"code":"400100","msg":"Order size below the minimum requirement."}
          "Order size increment invalid.": InvalidOrder,
          // {"msg":"Order size increment invalid.","code":"600100"}
          "The withdrawal amount is below the minimum requirement.": ExchangeError,
          // {"code":"400100","msg":"The withdrawal amount is below the minimum requirement."}
          "Unsuccessful! Exceeded the max. funds out-transfer limit": InsufficientFunds,
          // {"code":"200000","msg":"Unsuccessful! Exceeded the max. funds out-transfer limit"}
          "The amount increment is invalid.": BadRequest,
          "The quantity is below the minimum requirement.": InvalidOrder,
          // {"msg":"The quantity is below the minimum requirement.","code":"400100"}
          "not in the given range!": BadRequest,
          // {"msg":"price not in the given range!","code":"400100"}
          "recAccountType not in the given range": BadRequest,
          // {"msg":"recAccountType not in the given range","code":"400100"}
          "Unsupported trading pair.": BadSymbol,
          // {"msg":"Unsupported trading pair.","code":"400100"}
          "400": BadRequest,
          "401": AuthenticationError,
          "403": NotSupported,
          "404": NotSupported,
          "405": NotSupported,
          "415": NotSupported,
          "429": RateLimitExceeded,
          "429000": RateLimitExceeded,
          // {"code":"429000","msg":"Too many requests. System-level rate limit exceeded."}
          "500": ExchangeNotAvailable,
          // Internal Server Error -- We had a problem with our server. Try again later.
          "503": ExchangeNotAvailable,
          "101030": PermissionDenied,
          // {"code":"101030","msg":"You haven't yet enabled the margin trading"}
          "103000": InvalidOrder,
          // {"code":"103000","msg":"Exceed the borrowing limit, the remaining borrowable amount is: 0USDT"}
          "112010": PermissionDenied,
          // {"msg":"Invalid Unified Account user.","code":"112010"}
          "130101": BadRequest,
          // Parameter error
          "130102": ExchangeError,
          // Maximum subscription amount has been exceeded.
          "130103": OrderNotFound,
          // Subscription order does not exist.
          "130104": ExchangeError,
          // Maximum number of subscription orders has been exceeded.
          "130105": InsufficientFunds,
          // Insufficient balance.
          "130106": NotSupported,
          // The currency does not support redemption.
          "130107": ExchangeError,
          // Redemption amount exceeds subscription amount.
          "130108": OrderNotFound,
          // Redemption order does not exist.
          "130201": PermissionDenied,
          // Your account has restricted access to certain features. Please contact customer service for further assistance
          "130202": ExchangeError,
          // The system is renewing the loan automatically. Please try again later
          "130203": InsufficientFunds,
          // Insufficient account balance
          "130204": BadRequest,
