          // {"code":412,"msg":"Missing parameter - resolution","data":null}
          "6001": BadRequest,
          // {"error":{"code":6001,"message":"invalid argument"},"id":null,"result":null}
          // documented
          "19999": BadRequest,
          // REQUEST_IS_DUPLICATED Duplicated request ID
          "10001": DuplicateOrderId,
          // OM_DUPLICATE_ORDERID Duplicated order ID
          "10002": OrderNotFound,
          // OM_ORDER_NOT_FOUND Cannot find order ID
          "10003": CancelPending,
          // OM_ORDER_PENDING_CANCEL Cannot cancel while order is already in pending cancel status
          "10004": CancelPending,
          // OM_ORDER_PENDING_REPLACE Cannot cancel while order is already in pending cancel status
          "10005": CancelPending,
          // OM_ORDER_PENDING Cannot cancel while order is already in pending cancel status
          "11001": InsufficientFunds,
          // TE_NO_ENOUGH_AVAILABLE_BALANCE Insufficient available balance
          "11002": InvalidOrder,
          // TE_INVALID_RISK_LIMIT Invalid risk limit value
          "11003": InsufficientFunds,
          // TE_NO_ENOUGH_BALANCE_FOR_NEW_RISK_LIMIT Insufficient available balance
          "11004": InvalidOrder,
          // TE_INVALID_LEVERAGE invalid input or new leverage is over maximum allowed leverage
          "11005": InsufficientFunds,
          // TE_NO_ENOUGH_BALANCE_FOR_NEW_LEVERAGE Insufficient available balance
          "11006": ExchangeError,
          // TE_CANNOT_CHANGE_POSITION_MARGIN_WITHOUT_POSITION Position size is zero. Cannot change margin
          "11007": ExchangeError,
          // TE_CANNOT_CHANGE_POSITION_MARGIN_FOR_CROSS_MARGIN Cannot change margin under CrossMargin
          "11008": ExchangeError,
          // TE_CANNOT_REMOVE_POSITION_MARGIN_MORE_THAN_ADDED exceeds the maximum removable Margin
          "11009": ExchangeError,
          // TE_CANNOT_REMOVE_POSITION_MARGIN_DUE_TO_UNREALIZED_PNL exceeds the maximum removable Margin
          "11010": InsufficientFunds,
          // TE_CANNOT_ADD_POSITION_MARGIN_DUE_TO_NO_ENOUGH_AVAILABLE_BALANCE Insufficient available balance
          "11011": InvalidOrder,
          // TE_REDUCE_ONLY_ABORT Cannot accept reduce only order
          "11012": InvalidOrder,
          // TE_REPLACE_TO_INVALID_QTY Order quantity Error
          "11013": InvalidOrder,
          // TE_CONDITIONAL_NO_POSITION Position size is zero. Cannot determine conditional order's quantity
          "11014": InvalidOrder,
          // TE_CONDITIONAL_CLOSE_POSITION_WRONG_SIDE Close position conditional order has the same side
          "11015": InvalidOrder,
