          // Deposit is not available
          "WITHDRAW_001": BadRequest,
          // Withdraw is not open
          "WITHDRAW_002": BadRequest,
          // The withdrawal address is invalid
          "WITHDRAW_003": PermissionDenied,
          // The current account security level is low, please bind any two security verifications in mobile phone/email/Google Authenticator before withdraw
          "WITHDRAW_004": BadRequest,
          // The withdrawal address is not added
          "WITHDRAW_005": BadRequest,
          // The withdrawal address cannot be empty
          "WITHDRAW_006": BadRequest,
          // Memo cannot be empty
          "WITHDRAW_008": PermissionDenied,
